+import ts from 'typescript';
+import { z } from 'zod';
+
+export function inferSchema(sourceFile: ts.SourceFile, typeName: string) {
+  const checker = /* get checker */;
+  const type = checker.getTypeAtLocation(
+    sourceFile.statements.find(
+      (s): s is ts.TypeAliasDeclaration =>
+        ts.isTypeAliasDeclaration(s) && s.name.text === typeName
+    )!
+  );
+
+  return typeToZod(type, checker);
+}
+
+function typeToZod(type: ts.Type, checker: ts.TypeChecker): z.ZodTypeAny {
+  if (type.flags & ts.TypeFlags.String) return z.string();
+  if (type.flags & ts.TypeFlags.Number) return z.number();
+  if (type.flags & ts.TypeFlags.Boolean) return z.boolean();
+
+  const properties = checker.getPropertiesOfType(type);
+  if (properties.length > 0) {
+    const shape: Record<string, z.ZodTypeAny> = {};
+    for (const prop of properties) {
+      shape[prop.name] = typeToZod(
+        checker.getTypeOfSymbolAtLocation(prop, prop.valueDeclaration!),
+        checker
+      );
+    }
+    return z.object(shape);
+  }
+
+  return z.unknown();
+}
